{
  "code": "async (page) => {
  await page.waitForLoadState('networkidle');
  // select criteria on homepage
  await page.selectOption('form.findus select[name="tipoInmueble[]"]', 'piso');
  await page.selectOption('form.findus select[name="municipio[]"]', 'Hendaye');
  await Promise.all([
    page.waitForNavigation({ waitUntil: 'networkidle' }),
    page.click('form.findus button[type="submit"]')
  ]);

  const results = [];
  await page.waitForSelector('.easyPaginateNav a.page', {timeout: 10000});
  const pageLinks = await page.$$eval('.easyPaginateNav a.page', els => els.map(e => e.getAttribute('rel')).filter(Boolean));
  const maxPages = Math.min(20, pageLinks.length || 1);
  const timestamp = new Date().toISOString();

  for (let i = 0; i < maxPages; i++) {
    const pageNum = pageLinks[i] || (i + 1).toString();
    // Click each page control
    const pager = page.locator(`.easyPaginateNav a.page[rel="${pageNum}"]`);
    if (await pager.count()) {
      await pager.first().click();
      await page.waitForTimeout(600);
    }

    const pageResults = await page.$$eval('.easyPaginateList .col-inmueble', (nodes, timestamp, baseUrl) => {
      return nodes.filter(node => {
        const style = window.getComputedStyle(node);
        return style.display !== 'none' && node.offsetParent !== null;
      }).map(node => {
        const linkEl = node.querySelector('.proerty_text h3 a');
        const title = linkEl ? linkEl.textContent.trim().replace(/\s+/g, ' ') : '';
        const detailUrl = linkEl ? linkEl.href.trim() : '';
        const locationEl = node.querySelector('.proerty_text > span');
        const location = locationEl ? locationEl.textContent.trim().replace(/\s+/g, ' ') : '';
        const priceEl = node.querySelector('.favroute .price');
        const price = priceEl ? priceEl.textContent.trim().replace(/\s+/g, ' ') : '';
        const idMatch = detailUrl.match(/(\d+)\/?$/);
        const stableId = idMatch ? idMatch[1] : detailUrl;
        return { title, price, location, detailUrl, stableId, scrapingTimestamp: timestamp };
      });
    }, timestamp);

    // append unique across pagination
    for (const r of pageResults) {
      if (!results.some(e => e.detailUrl === r.detailUrl)) {
        results.push(r);
      }
    }
  }
  return results;
}"
}

