## 🛠 Script Playwright Node.js (headless)

```js
// scrape_iparralde.js
const { chromium } = require('playwright');

(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();
  await page.goto('https://inmobiliariaiparralde.com/', { waitUntil: 'networkidle' });

  // 1) Seleccionar filtros
  await page.selectOption('form.findus select[name="tipoInmueble[]"]', 'piso');
  await page.selectOption('form.findus select[name="municipio[]"]', 'Hendaye');

  // 2) clic Search
  await Promise.all([
    page.waitForNavigation({ waitUntil: 'networkidle' }),
    page.click('form.findus button[type="submit"]')
  ]);

  // 3) función parseador de página visible
  const parseCurrentPage = async () => {
    const now = new Date().toISOString();
    const items = await page.$$eval('#easyPaginate-1 .property-list-list', entries =>
      entries
        .filter(e => window.getComputedStyle(e).display !== 'none' && e.offsetParent !== null)
        .map(entry => {
          const info = entry.querySelector('.property-list-list-info');
          const link = entry.querySelector('a.wi')?.href?.trim() || '';
          const title = entry.querySelector('a.wi img')?.alt?.trim()
            || info?.querySelector('h3')?.textContent?.trim()
            || '';
          const price = info?.querySelector('.price')?.textContent?.trim() || '';
          const raw = info?.textContent || '';
          let location = '';
          const locMatch = raw.match(/\\d{5}\\s+[^\\n,]+,\\s*(ES|FR)/i);
          if (locMatch) location = locMatch[0].trim();
          const stableId = link.match(/(\\d+)\\/?$/)?.[1] || '';
          return { title, price, location, detailUrl: link, stableId, scrapingTimestamp: now };
        })
    );
    return items;
  };

  const all = [];
  const pageRelList = await page.$$eval('.easyPaginateNav a.page', anchors =>
    anchors.map(a => a.getAttribute('rel')).filter(Boolean)
  );

  for (const rel of pageRelList) {
    await page.click(`.easyPaginateNav a.page[rel="${rel}"]`);
    await page.waitForTimeout(700); // permite que easyPaginate muestre items
    const items = await parseCurrentPage();
    for (const i of items) {
      if (!all.some(existing => existing.detailUrl === i.detailUrl)) all.push(i);
    }
  }

  console.log(JSON.stringify(all, null, 2));
  await browser.close();
})();
```

### ▶️ Ejecutar
1. `npm i playwright`
2. `node scrape_iparralde.js`

